import{_ as e,c as a,o as r,a3 as s}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Recruitment","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/index.md","filePath":"master/human-resources/recruitment/index.md","lastUpdated":1791902625000}'),o={name:"master/human-resources/recruitment/index.md"};function i(n,t,d,h,l,p){return r(),a("div",null,t[0]||(t[0]=[s(`<h1 id="recruitment" tabindex="-1">Recruitment <a class="header-anchor" href="#recruitment" aria-label="Permalink to &quot;Recruitment&quot;">​</a></h1><p>The Recruitment app helps you fill open roles. You keep each role as a job position, record every person who applies, and move each applicant through hiring stages. When someone is hired, you turn the applicant into an employee with one button. If someone is not a fit, you refuse the application with a reason and can reopen it later.</p><blockquote><p><strong>In simple words:</strong> Recruitment is the place where you track who applied for which job and how far each person has got.</p></blockquote><p>Open the <strong>Recruitment</strong> app from the main menu for the dashboard. Open <strong>Recruitments</strong> for the daily work. It has two tabs: <strong>Applications</strong> and <strong>Configuration</strong>.</p><h2 id="how-an-applicant-moves-through-aureus" tabindex="-1">How an applicant moves through Aureus <a class="header-anchor" href="#how-an-applicant-moves-through-aureus" aria-label="Permalink to &quot;How an applicant moves through Aureus&quot;">​</a></h2><p>Follow these steps in order the first time.</p><ol><li>Define the job position, for example <strong>Warehouse Supervisor</strong>.</li><li>An applicant arrives. You add the person and link the job position.</li><li>The applicant moves through stages, from <strong>New</strong> to <strong>Contract Signed</strong>.</li><li>At a hired stage, the applicant is marked <strong>Hired</strong> and you create the employee.</li><li>Or you refuse the applicant with a reason. You can reopen the application later.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Job position ──► Applicant added ──► Stages ──► Hired ──► Employee created</span></span>
<span class="line"><span>                                       │</span></span>
<span class="line"><span>                                       └──► Refused (reopen with Restore)</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Start here</p><p>The <a href="./get-started/first-steps.html">first steps tutorial</a> follows one applicant, <strong>Rahul Verma</strong>, from first contact to employee.</p></div><h2 id="the-menus" tabindex="-1">The menus <a class="header-anchor" href="#the-menus" aria-label="Permalink to &quot;The menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Recruitment</strong> (dashboard)</td><td>Filters, three number cards and a chart of applicants by status. See <a href="./dashboard/recruitment-dashboard.html">Recruitment dashboard</a>.</td></tr><tr><td><strong>Applications → Job Positions</strong></td><td>One card per open role with applicant counts. See <a href="./job-positions/job-positions.html">Job positions</a>.</td></tr><tr><td><strong>Applications → Applicants</strong></td><td>The list of people who applied, grouped by stage. See <a href="./applicants/">Applicants</a>.</td></tr><tr><td><strong>Applications → Candidates</strong></td><td>The people behind the applications, with their contact details and skills. See <a href="./applicants/candidates.html">Candidates</a>.</td></tr><tr><td><strong>Configuration</strong></td><td>The lists that feed the forms. See <a href="./setup/">Setup</a>.</td></tr></tbody></table><h2 id="data-that-comes-ready-to-use" tabindex="-1">Data that comes ready to use <a class="header-anchor" href="#data-that-comes-ready-to-use" aria-label="Permalink to &quot;Data that comes ready to use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Record</th><th>What you will find</th></tr></thead><tbody><tr><td>Stages</td><td>New, First Interview, Initial Qualification, Second Interview, Document Verification, Contract Proposal, Contract Signed</td></tr><tr><td>Refuse reasons</td><td>Seven, such as <strong>Duplicate</strong> and <strong>Refused by applicant: salary</strong></td></tr><tr><td>Job positions</td><td>14, including <strong>Warehouse Supervisor</strong> and <strong>Software Engineer</strong></td></tr><tr><td>Applicants</td><td>Seven sample applicants, for example <strong>Chloe Dubois</strong> (Hired)</td></tr><tr><td>Tags, degrees, sources, mediums</td><td>Ready-made lists for the applicant form</td></tr></tbody></table><h2 id="pages-in-this-module" tabindex="-1">Pages in this module <a class="header-anchor" href="#pages-in-this-module" aria-label="Permalink to &quot;Pages in this module&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./get-started/">Get started</a></td><td>A guided first run with Rahul Verma</td></tr><tr><td><a href="./dashboard/recruitment-dashboard.html">Recruitment dashboard</a></td><td>Numbers and a chart with filters</td></tr><tr><td><a href="./job-positions/job-positions.html">Job positions</a></td><td>The roles you hire for</td></tr><tr><td><a href="./applicants/">Applicants</a></td><td>Add, process, refuse and list applicants, and candidates</td></tr><tr><td><a href="./setup/">Setup</a></td><td>Stages, refuse reasons, tags, degrees, sources and mediums</td></tr></tbody></table><h2 id="how-other-apps-use-recruitment" tabindex="-1">How other apps use Recruitment <a class="header-anchor" href="#how-other-apps-use-recruitment" aria-label="Permalink to &quot;How other apps use Recruitment&quot;">​</a></h2><ul><li><a href="./../employees/">Employees</a> supplies departments and job positions. Recruitment creates the employee profile when you hire.</li><li>Chatter and activities work as in the rest of Aureus. See <a href="./../../getting-started/chatter.html">Chatter</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./get-started/first-steps.html">Get started: first steps</a></li><li><a href="./../employees/">Employees overview</a></li><li><a href="./../../getting-started/search-filter-group.html">Search, filter and group</a></li></ul>`,19)]))}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
